"""Component L15 MLP down_proj #5313 (Qwen3-1.7B).

What it does: it fires on the whitespace that starts a new line of code, and on the
line break that ends a line opening a block ("{"), when the next thing is a new statement
in a code block. Its output direction promotes the token "return" (and "Return"), so it is
part of the model's "a statement comes next, probably return" signal. It is near zero on
prose and on most other tokens, and a little below zero where a line breaks after a
continuation character ("," "(" "[" and similar).

The program predicts its activation from the text so far, with readable rules:
  * a whitespace-only token that starts a line (only spaces or line numbers before it):
    large for tab indentation, smaller for space indentation, and it depends on how the
    previous line ended. After a statement end ("{", "}", ";", ":") it is large; after
    ")" it is medium; after a continuation ("," "(" "." or an operator) it is near zero.
  * a whitespace-only token in the middle of a line -> small;
  * a token that ends a line with "{" -> large; with ";" or "}" -> small;
    with ")" ":" or '"' -> small; with "," "(" "[" or an operator -> slightly negative;
  * everything else -> 0.
"""

import re

READS = ()

INDENT = re.compile(r"[ \t\xa0]+")
LINE_START = re.compile(r"[\s\d|]*")  # the line so far holds only spaces or line numbers
CONTINUATION = set(",(.+=-*&|<>[")  # a line ending like this continues onto the next line
STATEMENT_END = set("{};:")

# typical activation at a line-start indent, by indent kind and previous line's ending
TAB_INDENT = {"end": 5.0, "paren": 3.4, "continue": 0.2, "other": 3.0, "none": 0.0}
SPACE_INDENT = {"end": 2.4, "paren": 1.4, "continue": 0.0, "other": 0.5, "none": 0.0}
# typical activation of a token that ends a line, by the last character before the line break
LINE_BREAK = {"{": 3.1, ";": 0.9, "}": 0.9, ")": 0.5, ":": 0.4, '"': 0.5}
LINE_BREAK.update({c: -0.5 for c in ",([*%"})


def line_end_kind(c):
    if c in STATEMENT_END:
        return "end"
    if c == ")":
        return "paren"
    if c in CONTINUATION:
        return "continue"
    return "other"


def step(carry, prefix, upstream):
    if carry is None or len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        line, last_end = "", "none"  # new document: fresh state
    else:
        line, last_end = carry
    tok = prefix.token_strings[-1]

    if INDENT.fullmatch(tok):
        if LINE_START.fullmatch(line):
            table = TAB_INDENT if "\t" in tok else SPACE_INDENT
            value = table[last_end]
        else:
            value = 0.2
    elif "\n" in tok:
        value = LINE_BREAK.get(tok.rstrip()[-1:], 0.0)
    else:
        value = 0.0

    # update the current line and the ending of the last non-blank line
    for ch in tok:
        if ch == "\n":
            if line.strip():
                last_end = line_end_kind(line.rstrip()[-1])
            line = ""
        else:
            line += ch
    return (line, last_end), value

"""Predicts layers.15.mlp.down_proj component 5319 (the MLP hidden unit 5319 of layer 15).

What it does: the unit is near zero almost everywhere, with a diffuse +/-1 texture that
no short rule captures. Its clearest behaviour is on words about what happens because of
something: "result", "consequence", "outcome", "effect", "impact", "cost", "benefit" and
their kin. In ordinary English prose these push the activation negative, most after a
determiner ("the result", "a consequence"); in code ("return result", "result = ...") they
do nothing. Auxiliary verbs (is, are, was, has, will ...) lean slightly negative and
prepositions (of, with, by, to ...) slightly positive. Everything else predicts 0.
Values are least-squares scaled to the activation, so the sizes are the fitted ones.
"""

READS = ()

OUTCOME_WORDS = {
    "result", "results", "resulted", "resulting", "consequence", "consequences",
    "consequently", "outcome", "outcomes", "effect", "effects", "impact", "impacts",
    "implication", "implications", "repercussion", "repercussions", "ramification",
    "ramifications", "fallout", "downside", "aftermath", "benefit", "benefits",
    "cost", "costs", "toll", "damage", "reward", "rewarded", "suffer", "suffered",
    "adverse", "casualties", "affected", "affects", "example", "examples",
}
DETERMINERS = {"the", "a", "an", "its", "their", "his", "her", "this", "that", "one", "final"}
AUXILIARIES = {
    "is", "are", "was", "were", "be", "been", "has", "have", "does", "do",
    "will", "would", "can", "could", "may", "should", "must",
}
PREPOSITIONS = {"of", "with", "by", "that", "for", "as", "in", "to"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
    if word in OUTCOME_WORDS:
        if previous in DETERMINERS:
            value = -1.5
        elif previous.isalpha():
            value = -1.0
        else:
            value = 0.0
    elif word in AUXILIARIES:
        value = -0.1
    elif word in PREPOSITIONS:
        value = 0.05
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP hidden unit 5335, read through its down-projection component.

This component is one hidden unit of the layer-15 MLP (its input direction is about
0.96 on unit 5335), so its activation is that unit's value, scaled. The unit is
diffuse: most tokens sit near zero (std about 0.9), and it moves strongly only in a
few place-name and date contexts. This program is a token-class rule that predicts
the group mean for the handful of contexts it recognises:

- month names ("September") and digits within three tokens of one ("August 1[7]"):
  negative, the middle of a date;
- place-type nouns ("County", "Street", "College"): negative, a place name ending;
- " in" after a verb of location ("located in", "live in"): mildly positive;
  any other " in" (usually "in 2007", "in the County"): negative;
- "administrative" and "territorial": positive, the words that introduce a named unit.

Everything else predicts 0. The rule explains only about 2% of the variance: the
activation is mostly context noise that no token rule captures.
"""

READS = ()

MONTHS = {
    "January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December",
}
PLACE_NOUNS = {
    "County", "Street", "Province", "College", "School", "Avenue", "Stadium",
    "Junction", "Gallery", "Observatory", "Medicine", "Hall", "Park", "Road",
    "University", "Institute", "Department", "District", "Village", "Township",
    "Region", "State",
}
UNIT_WORDS = {"administrative", "territorial"}
LOCATION_VERBS = {
    "located", "live", "lived", "living", "be", "is", "are", "was", "were",
    "based", "involved", "part", "participate", "employed", "included",
}

MEAN_MONTH = -2.8
MEAN_DIGIT_AFTER_MONTH = -1.7
MEAN_PLACE = -1.75
MEAN_IN_LOCATION = 0.45
MEAN_IN_OTHER = -0.9
MEAN_UNIT = 2.6


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    token = tokens[-1]
    word = token.strip()

    def same_doc_back(k):
        # the token k places back, if it is in the same document
        return len(tokens) > k and docs[-1 - k] == docs[-1]

    if token.startswith(" ") and word in MONTHS:
        return carry, MEAN_MONTH
    if token.startswith(" ") and word in PLACE_NOUNS:
        return carry, MEAN_PLACE
    if word in UNIT_WORDS:
        return carry, MEAN_UNIT
    if token == " in":
        before = tokens[-2].strip() if same_doc_back(1) else ""
        return carry, MEAN_IN_LOCATION if before in LOCATION_VERBS else MEAN_IN_OTHER
    if word.isdigit():
        for k in range(1, 4):
            if same_doc_back(k) and tokens[-1 - k].strip() in MONTHS:
                return carry, MEAN_DIGIT_AFTER_MONTH
    return carry, 0.0

"""Naming-introducer feature (layer 15 MLP, one hidden direction).

It fires on the word that introduces the name or technical term for a thing, in
expository prose: "X is called Y", "also known as Y", "referred to as Y", "so-called Y",
"termed Y", "dubbed Y", "nicknamed Y", "se llama Y", and the Chinese 称为 / 被称为 /
叫做 / 简称 / 所谓 / 以下简称. Its value is the activation the program predicts at each
token: a strength for that word, and near zero everywhere else. In code, and in
sentences about program flow ("this method is called when ..."), it is switched down.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words that introduce a name, with their typical activation.
NAME_WORDS = {
    "called": 18.0, "-called": 25.0, "termed": 25.0, "dubbed": 21.0, "nicknamed": 22.0,
    "titled": 14.0, "entitled": 6.0, "named": 8.0, "known": 6.0, "referred": 7.0,
    "denoted": 6.0, "denote": 6.0, "aka": 10.0, "abbreviated": 6.0, "renamed": 7.0,
    "designated": 4.0, "labeled": 5.0, "labelled": 8.0, "spelled": 5.0, "nickname": 7.0,
    "llama": 17.0, "llamado": 15.0, "llamada": 15.0, "appelé": 10.0, "appelée": 10.0,
    "genannt": 6.0, "heißt": 6.0,
    "称为": 28.0, "被称为": 30.0, "叫做": 24.0, "简称": 22.0, "所谓": 22.0, "以下简称": 30.0,
    "下称": 30.0, "名为": 12.0, "名叫": 12.0, "叫": 9.0, "称": 7.0, "稱": 10.0, "叫我": 13.0,
}
CALL_WORDS = {"call", "calls", "calling"}
CALL_AFTER = {"we", "i", "they", "you", "would", "might", "could", "can", "will", "often", "people"}
ADVERB_BEFORE = {"also", "often", "sometimes", "commonly", "usually", "so", ","}
PERSON_BEFORE = {"he", "she", "they", "i", "we", "you", "me", "him", "them", "had", "have", "has", "somebody"}
AS_AFTER = {"known", "referred", "termed", "named", "simply", "described", "describes", "abbreviated"}
# Code and program-flow words, symbols and indentation: where the word is not a naming.
CODE = re.compile(r"(method|function|listener|trigger|handler|callback|variable|"
                  r"\(\)|\{|\}|;|//|\bthis\b|\bself\b|\bsetter|\bnull\b|\btrue\b|\bfalse\b|\n\s{2,})",
                  re.I)


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if prefix.position > 0 else ""
    recent = prefix.token_strings[-6:]
    if prefix.position > 0 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    if word == "as":
        value = 20.0 if prev in AS_AFTER or prev == "to" else 0.0
    elif word == "to":
        value = 20.0 if prev == "referred" else 0.0
    elif word in CALL_WORDS:
        value = 15.0 if prev in CALL_AFTER else 3.0
    elif word == "called":
        if prev in PERSON_BEFORE:
            value = 2.0  # "he called me": an action, not a name
        else:
            value = 28.0 if prev in ADVERB_BEFORE else 12.0 if prev in {"was", "were", "and"} else 18.0
    else:
        value = NAME_WORDS.get(word, 0.0)
    if value and CODE.search("".join(recent[:-1])):
        value *= 0.3
    return carry, value

"""Layer 15 MLP down-projection, component 5353: a preposition detector.

It fires on the small words that open a prepositional phrase ("in", "by", "of",
"from", "during", "via", ...) and on the article right after one ("in the", "of a").
The size depends on the word before it:
  - after a past participle ("obtained by", "included in", "shown in") it is about twice as big;
  - "of" after a part/whole or role noun ("result of", "member of", "part of", "president of")
    is the strongest case;
  - "to" after "according"/"answer"/"solution" (the "according to" frame) is strong.
Verbs of taking part in or fulfilling something ("satisfy", "await", "attend", "solve",
"participate", "join", "win") fire on the verb itself. Almost every other token gives ~0.
Activation is in the component's own units; SCALE was fitted on 4096 training rows.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

SCALE = 0.8

# How strongly each preposition fires on its own.
PREP_WEIGHT = {
    " during": 4.0, " via": 2.5, " by": 2.1, " in": 2.0, " under": 1.4, " through": 1.1,
    " at": 0.9, " of": 0.9, " after": 0.9, " from": 0.8, " for": 0.8, " against": 0.8,
    " into": 0.7, " on": 0.5, " to": 0.3,
}
# Verbs of participating in, fulfilling or completing something.
VERB_WEIGHT = {
    " satisfy": 4.0, " await": 4.0, " attend": 4.0, " solve": 3.0, " participate": 2.5,
    " perform": 2.3, " join": 2.3, " meet": 1.6, " win": 1.6, " complete": 1.2, " achieve": 1.2,
}
ARTICLES = {" the", " a", " an"}
PREPOSITIONS = {"in", "of", "on", "at", "by", "from", "for", "during", "within", "through",
                "to", "via", "under", "into", "after", "against"}
PART_OR_ROLE_NOUNS = {
    "result", "results", "outcome", "member", "members", "part", "parts", "end", "ends",
    "side", "sides", "top", "bottom", "edge", "edges", "center", "centre", "head", "element",
    "elements", "component", "components", "president", "director",
}
FRAME_WORDS_FOR_TO = {"according", "answer", "solution", "respond", "response"}
IRREGULAR_PARTICIPLES = {"given", "known", "shown", "written", "taken", "seen", "done", "made",
                         "held", "born", "built"}


def is_participle(word: str) -> bool:
    """A past participle, approximated by its ending."""
    return word.endswith("ed") or word in IRREGULAR_PARTICIPLES


def activation(token: str, before: str) -> float:
    """The predicted activation of one token, given the word before it ('' at a document start)."""
    if token in VERB_WEIGHT:
        return VERB_WEIGHT[token]
    if token in PREP_WEIGHT:
        value = PREP_WEIGHT[token]
        if is_participle(before):
            value *= 2.0
        if token == " of" and before in PART_OR_ROLE_NOUNS:
            value = 8.0
        if token == " to" and before in FRAME_WORDS_FOR_TO:
            value = 5.0
        return value
    if token in ARTICLES and before in PREPOSITIONS:
        return 2.0
    return 0.0


def step(carry, prefix, upstream: Mapping):
    same_document = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_document else ""
    return carry, float(SCALE * activation(prefix.token_strings[-1], before))
